// `musette-native` is generated by `npm run generate:android|ios` in
// modules/musette-native (crates/musette-ffi, uniffi-bindgen-react-native).
import * as ffi from 'musette-native';
import type { Capabilities, Core, DeviceField, Failure, Outcome, RouteAnalysis, Step } from './types';

/** Copy of the bytes as an ArrayBuffer of their own, as UniFFI takes them. */
const buf = (b: Uint8Array): ArrayBuffer => b.slice().buffer as ArrayBuffer;
const bytes = (b: ArrayBuffer): Uint8Array => new Uint8Array(b);
const num = (n: bigint | undefined): number | undefined => (n === undefined ? undefined : Number(n));

const field = (f: ffi.SettingField): DeviceField => ({ ...f, kind: f.kind as DeviceField['kind'] });

/** The record UniFFI carries, as the union the app uses. */
function outcome(o: ffi.Outcome): Outcome {
  switch (o.kind) {
    case 'info':
      return { kind: 'info', name: o.name, recording: o.recording };
    case 'activities':
      return {
        kind: 'activities',
        activities: o.activities.map((a) => ({ ...a, startTime: num(a.startTime), size: num(a.size) })),
      };
    case 'file':
      return { kind: 'file', bytes: bytes(o.bytes) };
    case 'settings':
      return { kind: 'settings', fields: o.fields.map(field), values: o.values };
    case 'failed':
      return { kind: 'failed', code: o.code as Failure['code'], detail: o.detail };
    default:
      return { kind: 'done' };
  }
}

const step = (s: ffi.Step): Step => ({
  subscribe: [...bytes(s.subscribe)],
  writes: s.writes.map((w) => ({ channel: w.channel, bytes: bytes(w.bytes) })),
  progress: s.progress,
  waitMs: s.waitMs,
  outcome: s.outcome && outcome(s.outcome),
});

/** UniFFI errors carry the musette-core message: rethrow it as a plain Error. */
function plain<T>(f: () => T): T {
  try {
    return f();
  } catch (e) {
    if (ffi.FfiError.Core.instanceOf(e)) throw new Error(e.inner.message);
    throw e;
  }
}

/** iOS and Android: the Rust core linked into the app (UniFFI). */
export async function loadPlatformCore(): Promise<Core> {
  await ffi.uniffiInitAsync();
  return {
    analyzeRoute: (lats, lons, eles) => plain(() => ffi.analyzeRoute(lats, lons, eles) as RouteAnalysis),
    parseGpx: (text) => plain(() => ffi.parseGpx(text)),
    verifyFit: (b) => plain(() => ffi.verifyFit(buf(b))),
    brytonFindActivities: (paths, sizes) =>
      ffi.brytonFindActivities(paths, sizes).map((a) => ({ id: a.id, size: num(a.size) })),
    capabilities: (model, link) => plain(() => ffi.capabilities(model, link) as Capabilities),
    settingFields: (model) => plain(() => ffi.settingFields(model).map(field)),
    session(model, timing) {
      const s = plain(() => new ffi.Session(model, timing?.requestMs, timing?.shortMs));
      return {
        channels: () => s.channels(),
        connect: () => plain(() => step(s.connect())),
        listActivities: () => plain(() => step(s.listActivities())),
        download: (id, size) => plain(() => step(s.download(id, size === undefined ? undefined : BigInt(size)))),
        acknowledge: (id) => plain(() => step(s.acknowledge(id))),
        sendRoute: (r) => plain(() => step(s.sendRoute(r.name, r.lats, r.lons, r.eles))),
        sendFile: (kind, b) => plain(() => step(s.sendFile(kind, buf(b)))),
        readSettings: () => plain(() => step(s.readSettings())),
        writeSettings: (changes) => plain(() => step(s.writeSettings(changes))),
        onNotify: (channel, b) => step(s.onNotify(channel, buf(b))),
        onTimeout: () => step(s.onTimeout()),
        free: () => s.uniffiDestroy(),
      };
    },
    cc600Simulator(o = {}) {
      const d = new ffi.Cc600Simulator(o.window ?? 0, o.free ?? 0, o.settings ?? '', o.loseChunks ?? [], o.loseAcks ?? []);
      return {
        addActivity: (id, startTime, fit) => d.addActivity(id, BigInt(startTime), buf(fit)),
        write: (b) => d.write(buf(b)).map(bytes),
        disconnect: () => d.disconnect(),
        received: () => d.received(),
        committed: () => {
          const c = d.committed();
          return c && bytes(c);
        },
        chunkBytes: () => d.chunkBytes(),
        acked: () => d.acked(),
        settings: () => d.settings(),
        settingsWrites: () => d.settingsWrites(),
      };
    },
  };
}
